#rf-root,.hf-root{--x3:#5a4f47;font-family:var(--rf-font);color:var(--rf-text)}.stage{position:absolute;inset:0;}.cam{position:absolute;inset:0;animation:st-cam 6.5s linear both;}@keyframes st-cam{from{transform:scale(1)}to{transform:scale(1.02)}}.bd{position:absolute;inset:0;overflow:hidden;background:var(--rf-bg)}.tx{position:absolute;inset:0;background:var(--rf-surface);z-index:50}.tx-out{transform:translateY(101%);animation:tx-out 0.5s cubic-bezier(.76,0,.24,1) 6s both}@keyframes tx-out{to{transform:translateY(0)}}@keyframes st-rise{from{transform:translateY(120px)}to{transform:none}}
@keyframes st-pushin{from{transform:translateX(100%)}to{transform:none}}
@keyframes st-pushout{to{transform:translateX(-100%)}}
@keyframes st-zoomin{from{transform:scale(.92);opacity:0}to{transform:none;opacity:1}}
@keyframes st-zoomout{to{transform:scale(1.08);opacity:0}}
@keyframes st-fadein{from{opacity:0}to{opacity:1}}
@keyframes st-fadeout{to{opacity:0}}.rise{animation:k-rise .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-rise{from{opacity:0;transform:translateY(40px)}to{opacity:1;transform:none}}
.pop{animation:k-pop .7s cubic-bezier(.16,1,.3,1) both}@keyframes k-pop{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:none}}
.slide-l{animation:k-sl .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sl{from{opacity:0;transform:translateX(-80px)}to{opacity:1;transform:none}}
.slide-r{animation:k-sr .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sr{from{opacity:0;transform:translateX(80px)}to{opacity:1;transform:none}}
.fade{animation:k-fade .8s ease-out both}@keyframes k-fade{from{opacity:0}to{opacity:1}}.wrap{position:absolute;left:90px;right:90px;top:0;bottom:0;display:flex;flex-direction:column;justify-content:center}.mk-l{display:block}.mk-w{display:inline-block;overflow:hidden;vertical-align:top;padding:0 .02em .08em;margin-bottom:-.08em}
.mk-w>span{display:inline-block;animation:mk-up 0.9s cubic-bezier(.16,1,.3,1) both}
@keyframes mk-up{from{transform:translateY(105%)}to{transform:none}}.eb{display:inline-block;font:500 32px/1.2 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-muted)}.acc{color:var(--rf-accent);font-style:normal}@property --n50{syntax:'<integer>';inherits:false;initial-value:0}
.n50{counter-reset:n50 var(--n50);animation:n50-c 2.4s cubic-bezier(.16,1,.3,1) 0.6s both}
.n50::after{content:counter(n50,decimal)}
@keyframes n50-c{from{--n50:0}to{--n50:4}}.wrap>div:first-child{margin-bottom:36px}
h2{margin:0;font-size:64px;line-height:1.05;letter-spacing:-.03em;font-weight:600;color:var(--rf-muted)}
.big{font-size:210px;font-weight:600;letter-spacing:-.06em;line-height:1;margin-top:10px;font-variant-numeric:tabular-nums;transform-origin:left}
.cap{font-size:44px;font-weight:600;margin:6px 0 70px;color:var(--rf-text)}
.chart{position:relative}
.grid line{stroke:color-mix(in srgb,var(--rf-text) 12%,transparent);stroke-width:2;stroke-dasharray:6 10}
.ln{stroke-dasharray:1;stroke-dashoffset:1;animation:ld 2.4s cubic-bezier(.76,0,.24,1) 0.6s both}
@keyframes ld{to{stroke-dashoffset:0}}
.area{opacity:0;animation:k-fade 1s ease-out 2.28s both}
.dot{fill:var(--rf-bg);stroke:var(--rf-accent);stroke-width:8;transform-box:fill-box;transform-origin:center;animation:k-pop .5s cubic-bezier(.16,1,.3,1) 3s both}
.xl{position:relative;height:50px;margin-top:24px}.xl span{position:absolute;transform:translateX(-50%);font:500 28px/1 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-muted)}
.xl span:first-child{transform:none}.xl span:last-child{transform:translateX(-100%)}

